reference_solution:
import { PrismaClient } from '@prisma/client';

// No global rejectOnNotFound in Prisma 5
// Use the OrThrow variants at the call site
const prisma = new PrismaClient();

async function getUserById(id: number) {
  // Throws PrismaClientKnownRequestError (P2025) if not found
  return prisma.user.findUniqueOrThrow({ where: { id } });
}

async function getLatestPost(authorId: number) {
  return prisma.post.findFirstOrThrow({
    where: { authorId },
    orderBy: { createdAt: 'desc' },
  });
}

