import { PrismaClient } from '@prisma/client';
const prisma = new PrismaClient();

// Use select OR include, not both
// Option 1: Use select to pick specific fields including relations
const user = await prisma.user.findUnique({
  where: { id: 1 },
  select: {
    name: true,
    email: true,
    posts: {
      select: { title: true, published: true },
    },
  },
});

// Option 2: Use include to add relations on top of all scalar fields
const userWithPosts = await prisma.user.findUnique({
  where: { id: 1 },
  include: { posts: true },
});

import { Prisma } from '@prisma/client';

// For nullable relations (Address.user?: User), use UserNullableRelationFilter
const addressFilter: Prisma.AddressWhereInput = {
  user: {
    // UserNullableRelationFilter allows 'is: null' and 'isNot: null'
    is: { name: 'Alice' },
  } satisfies Prisma.UserNullableRelationFilter,
};

// For non-nullable relations (Post.user: User), UserRelationFilter is still used
