reference_solution:
import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();

// Client extensions replace $use() middleware
const softDeleteExtension = Prisma.defineExtension({
  query: {
    post: {
      async delete({ args, query }) {
        // Instead of deleting, update with deletedAt timestamp
        return prisma.post.update({
          ...args,
          data: { ...args.data, deletedAt: new Date() },
        });
      },
    },
  },
});

const xprisma = prisma.$extends(softDeleteExtension);

// Usage
await xprisma.post.delete({ where: { id: 1 } }); // soft deletes

